## Pattern 1: Request/Response (Synchronous)

**Use Case**: Direct RPC-style calls where the caller blocks until receiving a response.

### JSON Schema

```json
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "title": "AgentRequest",
  "required": ["id", "agentId", "action", "payload", "timestamp"],
  "properties": {
    "id": { "type": "string", "format": "uuid" },
    "agentId": { "type": "string", "description": "Target agent identifier" },
    "action": { "type": "string", "description": "Action to invoke" },
    "payload": { "type": "object", "description": "Action parameters" },
    "timeout": { "type": "integer", "default": 30000, "minimum": 1000 },
    "correlationId": { "type": "string" },
    "timestamp": { "type": "string", "format": "date-time" }
  }
}
```

```json
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "type": "object",
  "title": "AgentResponse",
  "required": ["requestId", "status", "timestamp"],
  "properties": {
    "requestId": { "type": "string" },
    "status": { "type": "string", "enum": ["success", "error", "timeout"] },
    "data": { "type": "object" },
    "error": {
      "type": "object",
      "properties": {
        "code": { "type": "string" },
        "message": { "type": "string" }
      }
    },
    "duration": { "type": "integer", "description": "Processing time in ms" },
    "timestamp": { "type": "string", "format": "date-time" }
  }
}
```

### TypeScript Interface

```typescript
interface AgentRequest<T = Record<string, unknown>> {
  id: string;
  agentId: string;
  action: string;
  payload: T;
  timeout?: number;
  correlationId?: string;
  timestamp: string;
}

interface AgentResponse<T = unknown> {
  requestId: string;
  status: 'success' | 'error' | 'timeout';
  data?: T;
  error?: { code: string; message: string };
  duration: number;
  timestamp: string;
}

interface RequestResponseClient {
  send<TRequest, TResponse>(
    request: AgentRequest<TRequest>
  ): Promise<AgentResponse<TResponse>>;

  registerHandler<TRequest, TResponse>(
    action: string,
    handler: (req: AgentRequest<TRequest>) => Promise<AgentResponse<TResponse>>
  ): void;
}
```

### Example Implementation

```typescript
import { randomUUID } from 'crypto';

class HttpAgentClient implements RequestResponseClient {
  private handlers = new Map<string, Function>();
  private baseUrl: string;

  constructor(baseUrl: string) {
    this.baseUrl = baseUrl;
  }

  async send<TRequest, TResponse>(
    request: AgentRequest<TRequest>
  ): Promise<AgentResponse<TResponse>> {
    const startTime = Date.now();
    const timeout = request.timeout || 30000;

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeout);

    try {
      const response = await fetch(`${this.baseUrl}/api/agents/${request.agentId}/invoke`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(request),
        signal: controller.signal
      });

      const data = await response.json();
      return {
        ...data,
        duration: Date.now() - startTime
      } as AgentResponse<TResponse>;
    } catch (error) {
      if (error instanceof Error && error.name === 'AbortError') {
        return {
          requestId: request.id,
          status: 'timeout',
          error: { code: 'TIMEOUT', message: `Request timed out after ${timeout}ms` },
          duration: Date.now() - startTime,
          timestamp: new Date().toISOString()
        };
      }
      throw error;
    } finally {
      clearTimeout(timeoutId);
    }
  }

  registerHandler<TRequest, TResponse>(
    action: string,
    handler: (req: AgentRequest<TRequest>) => Promise<AgentResponse<TResponse>>
  ): void {
    this.handlers.set(action, handler);
  }
}

// Usage: Worker side
const worker = new HttpAgentClient('http://localhost:3000');
worker.registerHandler('analyze', async (req) => {
  const result = await performAnalysis(req.payload);
  return {
    requestId: req.id,
    status: 'success',
    data: result,
    duration: 0,
    timestamp: new Date().toISOString()
  };
});

// Usage: Caller side
const client = new HttpAgentClient('http://localhost:3000');
const response = await client.send({
  id: randomUUID(),
  agentId: 'analyzer-worker-01',
  action: 'analyze',
  payload: { text: 'Analyze this content' },
  timestamp: new Date().toISOString()
});
```

