### Example Implementation

```typescript
import { randomUUID } from 'crypto';

class MessageQueuePubSub implements PubSubClient {
  private subscriptions = new Map<string, EventSubscription>();
  private handlers = new Map<string, Set<(event: AgentEvent) => void>>();
  private messageQueue: AgentEvent[] = [];

  async publish(event: AgentEvent): Promise<void> {
    this.messageQueue.push(event);

    const handlers = this.handlers.get(event.eventType);
    if (handlers) {
      handlers.forEach(handler => handler(event));
    }

    const wildcardHandlers = this.handlers.get('*');
    if (wildcardHandlers) {
      wildcardHandlers.forEach(handler => handler(event));
    }
  }

  async subscribe(subscription: EventSubscription): Promise<string> {
    const subscriptionId = randomUUID();
    this.subscriptions.set(subscriptionId, subscription);

    subscription.eventTypes.forEach(eventType => {
      if (!this.handlers.has(eventType)) {
        this.handlers.set(eventType, new Set());
      }
    });

    return subscriptionId;
  }

  async unsubscribe(subscriptionId: string): Promise<void> {
    this.subscriptions.delete(subscriptionId);
  }

  onEvent(eventType: string, handler: (event: AgentEvent) => void): void {
    if (!this.handlers.has(eventType)) {
      this.handlers.set(eventType, new Set());
    }
    this.handlers.get(eventType)!.add(handler);
  }
}

// Usage: Event emission
const eventBus = new MessageQueuePubSub();

await eventBus.publish({
  id: randomUUID(),
  eventType: 'task.completed',
  sourceAgent: 'worker-01',
  payload: { taskId: 'task-123', result: { status: 'completed' } },
  metadata: { priority: 'high' },
  timestamp: new Date().toISOString()
});

// Usage: Event subscription
await eventBus.subscribe({
  agentId: 'notification-agent',
  eventTypes: ['task.completed', 'task.failed'],
  endpoint: 'http://localhost:4000/webhook'
});

eventBus.onEvent('task.completed', async (event) => {
  console.log(`Task completed: ${event.payload.taskId}`);
  await sendNotification(event);
});
```

